// Hand-written questions for the Node.js Study Book assessment.
// h(topic, difficulty, question, options, explanation, code?) — options starting with "*" are correct.
export function addHandwritten(h) {
  // ---------------------------------------------------------------- 1 intro
  h("intro", "easy", "What is Node.js?", ["*A JavaScript runtime built on V8 that adds APIs for files, networking and processes", "A JavaScript framework for building web pages", "A new programming language compiled to JavaScript", "A browser engine without a user interface"], "Node is a runtime: V8 runs the JavaScript, libuv handles I/O, and core modules expose system APIs.");
  h("intro", "easy", "Which component of Node.js parses, compiles and runs your JavaScript code?", ["*V8", "libuv", "npm", "the node:fs module"], "V8 is Google's JavaScript engine, the same one used in Chrome.");
  h("intro", "medium", "Which component provides Node's event loop and the thread pool used for file system operations?", ["*libuv", "V8", "the OS kernel only", "npm"], "libuv is the C library that implements the event loop, async I/O and the worker pool.");
  h("intro", "easy", "Which of these exist as globals in Node.js? (select all that apply)", ["*process", "*fetch", "*globalThis", "window", "document"], "window and document are browser-only. process, fetch and globalThis exist in Node.");
  h("intro", "medium", "In the restaurant analogy, why can a single Node thread serve many clients at once?", ["*It starts I/O and moves on, handling each result when it is ready, instead of waiting", "It creates a new thread for each client automatically", "It runs all clients' code in parallel on every CPU core", "It caches every response so no waiting is needed"], "Non-blocking I/O: the single 'waiter' never stands still waiting for the 'kitchen' (the OS and libuv).");
  h("intro", "medium", "Which kind of work is Node's single main thread worst at?", ["*Long CPU-heavy computations", "Waiting for many network requests", "Reading many small files", "Serving thousands of idle WebSocket connections"], "CPU-bound work blocks the only JavaScript thread; I/O waiting does not.");
  h("intro", "easy", "Which Node release lines become Long-Term Support (LTS) releases?", ["*Even-numbered major versions", "Odd-numbered major versions", "Every major version", "Only versions ending in 0"], "Even majors are promoted to LTS in October; odd majors are Current-only and never LTS.");
  h("intro", "medium", "What does a .nvmrc file in a project folder contain?", ["*The Node version the project expects, read by version managers", "The list of npm dependencies", "Environment variables for Node", "Settings for Node's debugger"], "Version managers like nvm and fnm read .nvmrc (or .node-version) to switch to the project's Node version.");
  h("intro", "hard", "Why is a JavaScript micro-benchmark that times only the first few calls of a function misleading?", ["*V8 first interprets code and only optimises 'hot' functions after many calls", "The first calls always run on a slower thread", "Node caches function results after the first call", "Timers are inaccurate for the first second of a process"], "V8's tiered compilation (Ignition, then TurboFan) means early runs are slower than steady-state runs.");
  h("intro", "hard", "A browser developer asks why they no longer need Babel for a Node 26 backend. What is the best answer?", ["*You choose the Node version you deploy, so you can use every feature it supports natively", "Node translates all JavaScript to ES5 automatically", "Node ignores syntax it doesn't understand", "Babel doesn't work with Node"], "In the browser you can't control users' versions; on a server the runtime version is your decision.");

  // ---------------------------------------------------------------- 2 cli
  h("cli", "easy", "What does `node -p \"2 + 3\"` do?", ["*Evaluates the expression and prints 5", "Starts the REPL with 2 + 3 as the first input", "Runs a file named \"2 + 3\"", "Prints the expression without evaluating it"], "-p (print) evaluates the code and prints the result; -e evaluates without printing.");
  h("cli", "easy", "Which console method writes to standard error (stderr)?", ["*console.error", "console.log", "console.info", "console.table"], "console.error and console.warn write to stderr; log, info, table go to stdout.");
  h("cli", "medium", "Why should a command-line tool print diagnostics (progress, warnings) to stderr rather than stdout?", ["*So that piping or redirecting the tool's output passes only the real data", "Because stderr is faster than stdout", "Because stdout is only for errors", "Because stderr is shown in a different colour"], "Separating data (stdout) from diagnostics (stderr) makes tools composable with pipes and redirects.");
  h("cli", "easy", "What does `node --watch app.js` do?", ["*Runs app.js and restarts it whenever it or its imports change", "Runs app.js and prints every function call", "Starts a debugger watching app.js", "Watches app.js for syntax errors without running it"], "--watch is Node's built-in replacement for nodemon.");
  h("cli", "medium", "Which statement about process.env values is true?", ["*They are always strings (or undefined)", "Numbers are converted automatically", "They can hold objects", "They are read-only"], "Environment variables are strings; convert them explicitly (Number(...), === \"true\").");
  h("cli", "medium", "Which is the safest way to end a CLI script with a failure code without cutting off pending output?", ["*Set process.exitCode = 1 and let the program finish", "Call process.exit(1) immediately", "Throw a string", "Call process.kill(process.pid)"], "process.exit() terminates immediately and may lose pending writes; exitCode lets Node finish its work first.");
  h("cli", "medium", "Which command runs app.js with variables loaded from a .env file, without any npm package?", ["*node --env-file=.env app.js", "node --dotenv app.js", "node app.js < .env", "node --env .env app.js"], "--env-file loads the file before running; real environment variables still win.");
  h("cli", "hard", "Your tool asks two questions with readline/promises' question() and works in a terminal, but hangs when the answers are piped in. Why?", ["*Piped input arrives all at once, so a line read before the second question is asked is lost", "readline cannot read from pipes", "question() only works with TTYs and throws otherwise", "Piped input is read as binary"], "With piped stdin, readline consumes all lines immediately; use the async line iterator to buffer them.");
  h("cli", "easy", "In the analogy of environment variables as notes on the fridge, what does changing the notes correspond to?", ["*Changing configuration per machine without changing the program", "Rewriting the program's source code", "Restarting the operating system", "Installing new npm packages"], "Environment variables configure the same program differently on different machines.");
  h("cli", "hard", "A deploy script runs `node migrate.js && node server.js`. migrate.js catches errors and logs them with console.log. Why did the server start after a failed migration?", ["*migrate.js still exited with code 0, and && only checks the exit code", "&& ignores exit codes", "console.log always exits with 1", "node server.js ignores the previous command"], "Set process.exitCode = 1 after a caught failure so the shell sees it.");

  // ---------------------------------------------------------------- 3 modules
  h("modules", "easy", "Which file extension is always treated as CommonJS, whatever package.json says?", ["*.cjs", ".mjs", ".js", ".json"], ".cjs is always CommonJS and .mjs always ESM; .js follows the \"type\" field.");
  h("modules", "easy", "In an ES module, what replaces CommonJS's __dirname?", ["*import.meta.dirname", "process.cwd()", "module.dirname", "require.dirname"], "import.meta.dirname and import.meta.filename are the ESM equivalents.");
  h("modules", "medium", "Why does `exports = { hello }` export nothing in CommonJS?", ["*It only rebinds the local exports parameter; require returns module.exports", "exports is read-only", "CommonJS can only export functions", "exports must be called as a function"], "exports starts as a reference to module.exports; reassigning it breaks the link.");
  h("modules", "medium", "What happens when two files both require('./config.cjs')?", ["*The module runs once and both get the same cached exports object", "The module runs twice and each gets its own copy", "The second require throws", "The second file gets an empty object"], "Modules are cached after the first load, which makes them behave like singletons.");
  h("modules", "medium", "In an ESM project, `import { sum } from \"./utils\"` fails with ERR_MODULE_NOT_FOUND although utils.js exists. Why?", ["*ES modules require the full file name, including the .js extension", "ESM cannot import local files", "utils.js must be renamed to utils.mjs", "The import needs the node: prefix"], "Unlike CommonJS, ESM resolution doesn't guess extensions or index files.");
  h("modules", "medium", "What does the \"exports\" field in a package's package.json control?", ["*Which entry points other code may import; unlisted paths are private", "Which dependencies are installed", "Which files npm publishes", "Which Node versions can run the package"], "Importing an unlisted subpath fails with ERR_PACKAGE_PATH_NOT_EXPORTED.");
  h("modules", "hard", "When can CommonJS code `require()` an ES module in current Node versions?", ["*When the ES module has no top-level await", "Never; it must always use import()", "Only if the ES module has a default export", "Only with the --experimental-require flag"], "require(esm) is enabled by default (Node 22.12+/20.19+) but cannot wait for top-level await (ERR_REQUIRE_ASYNC_MODULE).");
  h("modules", "hard", "Where does Node look for a bare specifier like import \"lodash\" from /app/src/lib/x.js?", ["*In node_modules folders: /app/src/lib/node_modules, then /app/src/node_modules, then /app/node_modules, up to the root", "Only in a global folder for npm packages", "Only in /app/node_modules", "In the folder where node was started"], "Node walks up the directory tree looking for node_modules, like checking shelves from your room to the town library.");
  h("modules", "easy", "Why is the node: prefix (import fs from \"node:fs\") recommended?", ["*It makes clear the module is built in and can't be confused with an npm package", "It makes imports faster by caching them twice", "It is required for every built-in module", "It enables CommonJS interop"], "Some newer modules (node:test, node:sqlite) only work with the prefix.");
  h("modules", "hard", "What is the 'dual package hazard'?", ["*An app loading both the CJS and ESM builds of a package gets two separate copies with separate state", "A package that cannot be imported by either system", "Two packages with the same name on npm", "A package that exports both default and named exports"], "Conditional exports can lead to the same package being instantiated twice; keep state out of dual builds.");

  // ---------------------------------------------------------------- 4 npm
  h("npm", "easy", "Which file records the exact versions of every installed package, including dependencies of dependencies?", ["*package-lock.json", "package.json", ".npmrc", "node_modules/.bin"], "The lockfile makes installs reproducible; commit it.");
  h("npm", "easy", "Which command should a CI server use to install exactly what the lockfile specifies?", ["*npm ci", "npm install", "npm update", "npm install --latest"], "npm ci deletes node_modules and installs exactly the locked versions, failing on mismatches.");
  h("npm", "easy", "Where should a test framework be listed in package.json?", ["*devDependencies", "dependencies", "peerDependencies", "engines"], "Tools needed only for development and testing belong in devDependencies.");
  h("npm", "medium", "In semver 2.4.1, what does a change to 3.0.0 signal?", ["*Breaking changes", "Only bug fixes", "New backwards-compatible features", "A security patch only"], "MAJOR changes break compatibility; MINOR adds features; PATCH fixes bugs.");
  h("npm", "medium", "What does `node --run test` do differently from `npm test`?", ["*It runs the script without starting npm, so it's faster but skips pre/post scripts", "It runs the tests in parallel", "It runs only the first test file", "It installs dependencies first"], "node --run is a lightweight script runner without lifecycle hooks.");
  h("npm", "medium", "Why should node_modules not be committed to git?", ["*It is large and can always be rebuilt from package.json and the lockfile", "Git cannot store JavaScript files", "npm deletes it automatically", "It contains secrets"], "Reproducible installs come from the lockfile; node_modules goes in .gitignore.");
  h("npm", "hard", "What is the main supply-chain risk of `npx some-tool` with a mistyped name?", ["*npx may download and run a malicious look-alike package", "It installs the tool globally", "It deletes the lockfile", "It changes the Node version"], "Typosquatting packages exploit typos; prefer tools listed in your devDependencies.");
  h("npm", "medium", "What does the \"files\" field in package.json do when publishing?", ["*It is an allow-list of files to include in the published package", "It lists files that npm must download", "It lists files to delete before publishing", "It lists test files"], "Use it so tests, secrets and source maps you don't want stay out of the tarball; check with npm pack --dry-run.");
  h("npm", "hard", "Why is `private: true` recommended in an application's package.json?", ["*It prevents accidentally publishing the app to the registry", "It hides the app's code from users", "It makes npm install faster", "It disables npm scripts"], "npm refuses to publish packages marked private.");
  h("npm", "easy", "In the analogy of package.json as a shopping list, what is package-lock.json?", ["*The receipt listing exactly what was bought", "The supermarket", "The recipe", "The fridge"], "The lockfile pins exact versions so everyone gets identical dependencies.");

  // ---------------------------------------------------------------- 5 callbacks
  h("callbacks", "easy", "In Node's error-first convention, how is a callback called after a successful operation?", ["*callback(null, result)", "callback(result)", "callback(result, null)", "callback(true, result)"], "The first argument is the error (null on success), then the result.");
  h("callbacks", "medium", "Why can't a try/catch around setTimeout catch an error thrown inside the timer's callback?", ["*The try block has already finished when the callback runs later", "setTimeout swallows all errors", "Errors in timers are always ignored", "try/catch only works with promises"], "The callback runs in a later turn of the event loop, outside the try block.");
  h("callbacks", "medium", "What is wrong with `if (err) callback(err); callback(null, data);`?", ["*On error the callback is called twice, because there is no return", "Nothing, this is the standard pattern", "callback must never receive an error", "data must come first"], "Use `if (err) return callback(err);` so the callback runs exactly once.");
  h("callbacks", "medium", "What does 'releasing Zalgo' refer to?", ["*A function that calls its callback sometimes synchronously and sometimes asynchronously", "A callback that is never called", "A callback that throws", "Nesting callbacks more than three levels deep"], "Mixed sync/async callbacks cause unpredictable ordering; always be asynchronous (process.nextTick).");
  h("callbacks", "easy", "Which flow-control pattern runs tasks one after another, each starting when the previous one finishes?", ["*Series", "Fully parallel", "Limited parallel", "Race"], "Series is used when order matters or each step needs the previous result.");
  h("callbacks", "medium", "When running tasks fully in parallel, why should results be stored by index (results[i] = …) rather than pushed?", ["*Tasks finish in completion order, so push would scramble the original order", "push is slower than index assignment", "Arrays don't support push in callbacks", "Index assignment prevents errors"], "Completion order differs from start order; indexing preserves input order.");
  h("callbacks", "hard", "You need to download 10,000 files from a server that allows 10 connections. Which pattern fits?", ["*Limited parallel with a concurrency of 10", "Fully parallel", "Series", "A single callback for all files"], "Limited parallelism keeps a fixed number of tasks in flight, like a supermarket with ten tills.");
  h("callbacks", "easy", "Which utility converts an error-first callback function into one returning a promise?", ["*util.promisify", "util.callbackify", "Promise.resolve", "events.once"], "util.promisify wraps (args…, cb) functions; callbackify does the reverse.");
  h("callbacks", "hard", "Why does `JSON.parse(data)` inside an fs.readFile callback crash the process on invalid JSON?", ["*It throws synchronously inside the callback, outside any try/catch, becoming an uncaught exception", "readFile cannot read JSON files", "JSON.parse is asynchronous", "The callback receives a Buffer that JSON.parse rejects silently"], "Wrap parsing in try/catch inside the callback, or use promises with one try/catch.");
  h("callbacks", "medium", "Is the callback passed to Array.prototype.forEach asynchronous?", ["*No, forEach calls it synchronously", "Yes, always", "Only in Node, not in browsers", "Only for arrays longer than 1000 elements"], "Callbacks are not async by nature; the API that receives them decides.");

  // ---------------------------------------------------------------- 6 promises
  h("promises", "easy", "From which path do you import the promise-based file system API?", ["*node:fs/promises", "node:fs/async", "node:promises/fs", "node:fs (with { promises: true })"], "Most core modules have a /promises variant: fs, timers, stream, dns.");
  h("promises", "medium", "Three independent requests each take 100 ms. How long does `await a(); await b(); await c();` take, compared with `await Promise.all([a(), b(), c()])`?", ["*About 300 ms vs about 100 ms", "About 100 ms vs about 300 ms", "About 100 ms both", "About 300 ms both"], "Sequential awaits wait for each in turn; Promise.all runs them concurrently.");
  h("promises", "medium", "What happens in Node by default when a promise rejects and nothing handles it?", ["*Node prints the error and exits with code 1", "The rejection is silently ignored", "Node retries the promise", "Node logs a warning and continues"], "Unhandled rejections crash the process (like uncaught exceptions) so failures aren't silently lost.");
  h("promises", "medium", "When Promise.all rejects because one promise rejected, what happens to the other operations?", ["*They keep running in the background unless you cancel them, for example with an AbortSignal", "They are cancelled automatically", "They are retried", "They resolve to undefined"], "Promises can't be cancelled; pass a signal to operations that must stop.");
  h("promises", "easy", "Which combinator resolves with the first promise to FULFIL and ignores rejections unless all reject?", ["*Promise.any", "Promise.race", "Promise.all", "Promise.allSettled"], "Promise.any fails only with an AggregateError when every promise rejects.");
  h("promises", "hard", "Why does `try { return save(); } catch {…}` inside an async function fail to catch save()'s rejection?", ["*The function returns the promise before it settles, leaving the try block", "async functions can't use try/catch", "save() must be awaited outside the function", "catch only works with synchronous code"], "Use `return await save()` inside try blocks.");
  h("promises", "medium", "What is a 'floating promise'?", ["*A promise created without await or .catch, so its result and errors are ignored", "A promise that resolves twice", "A promise stored in a global variable", "A promise that never settles"], "Floating promises cause unhandled rejections and code that 'finishes' before its work.");
  h("promises", "medium", "How does AbortSignal.any([a, b]) behave?", ["*It aborts when either a or b aborts", "It aborts only when both abort", "It aborts after both time out", "It never aborts"], "Use it to combine a user cancel signal with a timeout.");
  h("promises", "hard", "Why cache the promise rather than the value when ten concurrent requests ask for the same slow resource?", ["*All callers share one in-flight operation instead of starting ten", "Promises use less memory than values", "Values can't be cached in a Map", "It makes the operation synchronous"], "Caching the promise deduplicates concurrent work; remove failed promises from the cache.");
  h("promises", "easy", "In the parcel-tracking analogy, what does `await` correspond to?", ["*Waiting at the door until the parcel arrives (or is reported lost)", "Ordering the parcel", "Cancelling the order", "Giving the tracking number to someone else"], "await pauses the async function until the promise settles.");

  // ---------------------------------------------------------------- 7 loop
  h("loop", "easy", "In which event-loop phase do setImmediate callbacks run?", ["*check", "timers", "poll", "close callbacks"], "The check phase comes right after the poll phase.");
  h("loop", "easy", "In which event-loop phase do most I/O callbacks (like fs.readFile's) run?", ["*poll", "timers", "check", "pending callbacks"], "The poll phase retrieves I/O events and runs their callbacks, and waits there when idle.");
  h("loop", "medium", "When are the process.nextTick queue and the promise microtask queue drained?", ["*After every callback, before the event loop continues", "Only once per loop iteration, in the check phase", "Only at the end of the program", "Only during the timers phase"], "Both queues run after each operation; nextTick first (except at the top level of an ES module).");
  h("loop", "medium", "Inside an I/O callback, which runs first: setImmediate(fn) or setTimeout(fn, 0)?", ["*setImmediate, always", "setTimeout, always", "It depends on system load", "They run at the same time"], "From the poll phase, the next phase is check (immediates); timers wait for the next iteration.");
  h("loop", "hard", "In the main module (not inside I/O), which runs first: setTimeout(fn, 0) or setImmediate(fn)?", ["*It is not guaranteed; it depends on process start-up timing", "Always setTimeout", "Always setImmediate", "Neither runs until I/O happens"], "Whether the 1 ms timer is already due when the loop starts varies between runs.");
  h("loop", "medium", "Why can a recursive chain of process.nextTick calls freeze a server?", ["*The nextTick queue is drained completely before the loop moves on, so I/O never gets a turn", "nextTick creates a new thread each time", "nextTick blocks the thread pool", "nextTick callbacks are slower than timers"], "Unlike setImmediate, nextTick callbacks added while draining run in the same drain.");
  h("loop", "medium", "What does calling .unref() on a timer do?", ["*The timer no longer keeps the process alive on its own", "It cancels the timer", "It makes the timer fire immediately", "It repeats the timer"], "Useful for background housekeeping timers.");
  h("loop", "hard", "Why does `process.nextTick(a); Promise.resolve().then(b);` at the top level of an ES module run b before a?", ["*ESM top-level code runs inside a promise job, so queued microtasks drain before the nextTick queue", "nextTick is disabled in ES modules", "Promises always run before nextTick", "ES modules reverse all queue orders"], "In CommonJS the order is a then b; inside callbacks both systems run nextTick first.");
  h("loop", "easy", "A timer is set with setTimeout(fn, 100). When does fn run?", ["*At the earliest after 100 ms, when the event loop reaches the timers phase", "Exactly after 100 ms, interrupting other code", "After 100 ms of CPU time", "Immediately, then again after 100 ms"], "The delay is a minimum; a busy thread delays it further.");
  h("loop", "hard", "A Node script's only pending work is `await new Promise(() => {})` at the top level of an ES module. What happens?", ["*Node exits with code 13 (unsettled top-level await) because nothing keeps the loop alive", "Node waits forever", "Node throws a TimeoutError", "Node exits with code 0 and prints nothing"], "A pending promise alone doesn't keep the event loop alive.");

  // ---------------------------------------------------------------- 8 events
  h("events", "easy", "Which method registers a listener that runs only the first time an event is emitted?", ["*once", "on", "prependListener", "emitOnce"], "once removes the listener after its first call.");
  h("events", "medium", "Is EventEmitter's emit() synchronous or asynchronous?", ["*Synchronous: it calls the listeners in order before returning", "Asynchronous: listeners run on the next tick", "Asynchronous: listeners run in the check phase", "It depends on the number of listeners"], "Events organise code; they don't make it asynchronous.");
  h("events", "medium", "What happens when an emitter emits \"error\" and no \"error\" listener is registered?", ["*emit throws the error, which usually crashes the process", "Nothing happens", "Node logs a warning and continues", "The error is queued until a listener is added"], "Always listen for error on streams, sockets and servers.");
  h("events", "medium", "Why does `emitter.off(\"data\", (x) => log(x))` fail to remove a listener added with the same code?", ["*It is a different function object; off needs the same reference", "off only works with once listeners", "Arrow functions can't be removed", "off requires the listener's index"], "Keep a reference to listeners you intend to remove.");
  h("events", "medium", "What triggers MaxListenersExceededWarning?", ["*Adding more than 10 listeners for one event on the same emitter", "Emitting more than 10 events per second", "Having more than 10 emitters", "A listener that runs longer than 10 ms"], "It usually reveals a leak, such as adding a listener per request.");
  h("events", "hard", "An async listener throws after an await. How can the rejection be routed to the emitter's \"error\" event?", ["*Create the emitter with { captureRejections: true }", "Use prependListener", "Wrap emit in try/catch", "Use events.once"], "Otherwise the rejected promise returned by the listener is unhandled.");
  h("events", "easy", "What does events.once(emitter, \"ready\") return?", ["*A promise resolving with an array of the event's arguments", "The emitter itself", "A boolean", "An async iterator"], "It rejects if the emitter emits error first, and accepts a signal for timeouts.");
  h("events", "medium", "Why does Node use process.nextTick to emit an event from a constructor?", ["*So the caller can attach listeners before the event fires", "Because constructors can't call emit", "To make the event run on another thread", "To avoid the max-listeners warning"], "Emitting synchronously in the constructor would happen before any listener exists.");
  h("events", "easy", "In the radio-station analogy, what is a listener?", ["*A radio tuned to a channel (event name) that reacts to broadcasts", "The station itself", "The channel's name", "The broadcast message"], "Emitters broadcast without knowing who listens; listeners subscribe by event name.");
  h("events", "hard", "What do you get from `for await (const [x] of events.on(emitter, \"tick\"))` when you break out of the loop?", ["*The listener is removed and iteration stops cleanly", "The emitter is destroyed", "An AbortError is thrown", "The loop restarts with the next event"], "events.on returns an async iterator that cleans up on break or abort.");

  // ---------------------------------------------------------------- 9 files
  h("files", "easy", "Relative paths passed to fs functions are relative to…", ["*the current working directory (where node was started)", "the file containing the code", "the user's home folder", "the project's package.json"], "Use import.meta.dirname for files that belong to your code.");
  h("files", "medium", "Why is `if (existsSync(f)) readFileSync(f)` considered a race condition?", ["*The file can be deleted or changed between the check and the read", "existsSync is asynchronous", "existsSync always returns true", "readFileSync can't read files checked by existsSync"], "Do the operation and handle ENOENT instead.");
  h("files", "medium", "How do you write a file 'atomically' so a crash never leaves it half-written?", ["*Write to a temporary file in the same folder, then rename it over the original", "Use writeFileSync instead of writeFile", "Use the 'a' flag", "Write the file twice"], "rename on the same file system replaces the file in one step.");
  h("files", "easy", "Which error code means 'no such file or directory'?", ["*ENOENT", "EEXIST", "EACCES", "EISDIR"], "ENOENT appears for wrong paths, missing parents or a wrong working directory.");
  h("files", "medium", "Where do asynchronous fs operations actually run?", ["*On libuv's thread pool, off the main thread", "On the main JavaScript thread", "In a separate Node process", "In the operating system kernel only, without threads"], "That's why they don't block the event loop, and why many at once may queue.");
  h("files", "hard", "A server builds paths with path.join(\"uploads\", userSuppliedName). What attack does this allow?", ["*Path traversal: a name like ../../etc/x escapes the uploads folder", "SQL injection", "Cross-site scripting", "Denial of service through ReDoS"], "Resolve the final path and check it stays inside the base folder, or generate names yourself.");
  h("files", "medium", "What does the 'wx' flag do in writeFile?", ["*Writes, but fails with EEXIST if the file already exists", "Writes and executes the file", "Appends to the file", "Opens the file read-only"], "x means exclusive creation.");
  h("files", "medium", "What happens if you forget to close FileHandles opened in a busy server?", ["*File descriptors leak until EMFILE: too many open files", "The files are deleted", "Nothing; they close when garbage-collected immediately", "Writes go to the wrong file"], "Always close in finally (or use await using).");
  h("files", "easy", "Which call creates a folder and all missing parent folders without failing if it exists?", ["*mkdir(path, { recursive: true })", "mkdir(path)", "mkdir(path, { force: true })", "mkdir(path, { parents: false })"], "recursive: true is the built-in replacement for the mkdirp package.");
  h("files", "hard", "Code importing \"./Utils.js\" works on a Mac but fails on a Linux server where the file is utils.js. Why?", ["*Linux file systems are usually case-sensitive; macOS's default isn't", "Linux doesn't support ES modules", "macOS adds .js automatically", "The server has an older Node"], "Keep file names lower-case and consistent.");

  // ---------------------------------------------------------------- 10 streams
  h("streams", "easy", "Why use a stream instead of readFile for a 4 GB file?", ["*A stream processes small chunks, so memory stays low and processing starts immediately", "Streams read files faster from disk", "readFile can't read text files", "Streams compress the data automatically"], "readFile loads everything into memory at once.");
  h("streams", "easy", "Which stream type is zlib.createGzip()?", ["*Transform", "Readable", "Writable", "Duplex only"], "A Transform takes input, changes it, and outputs the result.");
  h("streams", "medium", "Why is stream.pipeline preferred over .pipe()?", ["*pipeline forwards errors from any stage and destroys all streams on failure", "pipe doesn't support backpressure", "pipeline is synchronous", "pipe only works with files"], "With .pipe(), an error in the source leaves the destination open.");
  h("streams", "medium", "What does it mean when writable.write() returns false?", ["*The internal buffer is above highWaterMark; wait for 'drain' before writing more", "The write failed and the data is lost", "The stream has ended", "The chunk was too large and was split"], "This is the backpressure signal.");
  h("streams", "medium", "In the kitchen-sink analogy for backpressure, what is the 'fill line'?", ["*highWaterMark", "The drain event", "The Readable stream", "The pipeline function"], "When the sink reaches the fill line, write() returns false and the tap should stop.");
  h("streams", "hard", "Why is decoding each chunk of UTF-8 text separately with chunk.toString() risky?", ["*A multi-byte character can be split across two chunks", "toString() only supports ASCII", "Chunks are always compressed", "toString() changes the chunk in place"], "Use setEncoding('utf8') or a TextDecoder with { stream: true }.");
  h("streams", "medium", "What is object mode in streams?", ["*Streams that carry arbitrary JavaScript values instead of Buffers or strings", "Streams that can only be read once", "Streams that store objects in a database", "Streams that run in a worker thread"], "Readable.from(iterable) creates object-mode streams.");
  h("streams", "easy", "What is a TCP socket in stream terms?", ["*A Duplex stream", "A Transform stream", "A Readable stream only", "A Writable stream only"], "Data flows both ways independently.");
  h("streams", "hard", "What does Buffer.subarray return?", ["*A view sharing memory with the original buffer", "An independent copy", "A string", "A new buffer with the bytes reversed"], "Changing the view changes the original; copy with Buffer.from(view) if needed.");
  h("streams", "medium", "What is the default highWaterMark for fs.createReadStream chunks?", ["*64 KB", "16 bytes", "1 MB", "There is no limit"], "File read streams use 64 KiB; generic byte streams default to 16 KiB.");

  // ---------------------------------------------------------------- 11 http
  h("http", "easy", "Which status code means a resource was created?", ["*201", "200", "204", "302"], "201 Created, usually with a Location header.");
  h("http", "easy", "Which status code fits a request whose JSON body is malformed?", ["*400", "404", "500", "201"], "400 Bad Request: the client sent something unparseable.");
  h("http", "medium", "Why must you call res.end() exactly once in a Node HTTP handler?", ["*Without it the response never finishes and the client waits; calling it twice is an error", "end() closes the server", "end() is needed only for error responses", "end() sends the request headers"], "write() may be called many times; end() finishes the response.");
  h("http", "medium", "How do you read the body of an incoming request?", ["*Consume req as a Readable stream (e.g. for await) and concatenate the chunks", "req.body is filled automatically", "Call req.json()", "Read req.headers.body"], "Node's http module doesn't parse bodies; frameworks do it for you.");
  h("http", "medium", "Why limit the size of request bodies?", ["*Without a limit, a single client can send a huge body and exhaust server memory", "Node can't parse large JSON", "HTTP forbids bodies over 1 MB", "To make responses faster"], "Answer 413 when the limit is exceeded.");
  h("http", "hard", "An async request handler throws (a rejected promise) and has no try/catch. What happens?", ["*The rejection is unhandled: the client hangs and the process may crash", "Node automatically sends a 500", "The request is retried", "Only that request is cancelled silently"], "http.createServer ignores the handler's returned promise.");
  h("http", "medium", "What is the difference between 404 and 405?", ["*404: no such resource; 405: the resource exists but not with this method", "404: server error; 405: client error", "They mean the same", "405: not found; 404: method not allowed"], "A router knows the path but not the method → 405.");
  h("http", "medium", "What does server.close() do during a graceful shutdown?", ["*Stops accepting new connections and calls back when existing ones have finished", "Kills all connections immediately", "Restarts the server", "Closes only idle connections"], "Combine with closeIdleConnections() and a hard timeout.");
  h("http", "easy", "Which header tells the client the type of the response body?", ["*Content-Type", "Accept", "Content-Length", "Location"], "e.g. application/json; charset=utf-8.");
  h("http", "hard", "Why should a request URL be parsed with new URL(req.url, base) rather than string splitting?", ["*It handles query strings, encoding and repeated parameters correctly", "req.url is always absolute", "String splitting is not allowed in handlers", "URL objects are faster to send"], "searchParams.get/getAll decode values for you.");

  // ---------------------------------------------------------------- 12 fetch
  h("fetch", "easy", "Does fetch() reject when the server answers 404?", ["*No, it resolves; check res.ok or res.status", "Yes, always", "Only for GET requests", "Only when the body is empty"], "fetch only rejects on network failures (DNS, connection refused, abort).");
  h("fetch", "medium", "Where does fetch put the underlying network error code (like ECONNREFUSED)?", ["*err.cause.code", "err.code", "err.status", "err.message only"], "The TypeError 'fetch failed' wraps the real cause.");
  h("fetch", "medium", "Why must you set a timeout on outgoing requests in a server?", ["*A slow upstream would otherwise make your own requests pile up and hang", "fetch has a 1-second default timeout", "Timeouts make requests faster", "Servers forbid requests without timeouts"], "Use AbortSignal.timeout(ms).");
  h("fetch", "medium", "Which requests are safe to retry automatically after a timeout? (select all that apply)", ["*GET /orders", "*PUT /orders/7", "*DELETE /orders/7", "POST /orders (no idempotency key)"], "Idempotent methods can be repeated safely; a plain POST may create duplicates.");
  h("fetch", "easy", "What library powers Node's built-in fetch?", ["*undici", "axios", "node-fetch", "request"], "undici is the HTTP client maintained by the Node team.");
  h("fetch", "medium", "How do you stream a fetch response body to a file?", ["*pipeline(Readable.fromWeb(res.body), createWriteStream(path))", "await res.json() then writeFile", "res.pipe(file)", "fs.copyFile(res.url, path)"], "res.body is a web ReadableStream; convert it for Node's pipeline.");
  h("fetch", "hard", "What is the danger of setting NODE_TLS_REJECT_UNAUTHORIZED=0 to work around certificate errors behind a corporate proxy?", ["*It disables certificate checking for every connection, enabling man-in-the-middle attacks", "It slows down all requests", "It breaks HTTP/1.1", "It only affects npm"], "Trust the company CA with NODE_EXTRA_CA_CERTS or --use-system-ca instead.");
  h("fetch", "medium", "What does a circuit breaker do?", ["*After repeated failures it fails fast for a while instead of calling the struggling service", "It retries every request forever", "It caches every response", "It splits requests across servers"], "It protects both your service and the dependency while it recovers.");
  h("fetch", "easy", "Which global gives Node a WebSocket client without packages?", ["*WebSocket", "Socket", "WebSocketServer", "net.WebSocket"], "Node includes the browser-compatible WebSocket client; servers usually use the ws package.");
  h("fetch", "hard", "Why can a response body be read only once (res.json() then res.text() fails)?", ["*The body is a stream; reading it consumes it", "fetch deletes the body after parsing", "text() only works before json()", "Bodies are cached only for GET"], "Clone the response (res.clone()) if you need to read it twice.");

  // ---------------------------------------------------------------- 13 concurrency
  h("concurrency", "easy", "What is the default size of libuv's thread pool?", ["*4 threads", "1 thread", "One per CPU core", "128 threads"], "Change it with the UV_THREADPOOL_SIZE environment variable before start-up.");
  h("concurrency", "medium", "Which of these use libuv's thread pool? (select all that apply)", ["*fs.promises.readFile", "*crypto.scrypt", "*zlib.gzip", "an incoming TCP connection", "JSON.parse"], "Network I/O uses OS async mechanisms; JSON.parse runs on the main thread.");
  h("concurrency", "medium", "What is ReDoS?", ["*A denial of service caused by a regular expression with catastrophic backtracking", "A Redis-based denial of service", "Repeated DNS lookups", "A recursive directory scan"], "Nested quantifiers like (a+)+ can take exponential time on near-matching input.");
  h("concurrency", "medium", "When should you use worker_threads?", ["*For CPU-heavy JavaScript work that would block the event loop", "For every HTTP request", "To make network requests faster", "To share variables between modules"], "I/O is already asynchronous; workers help with computation.");
  h("concurrency", "medium", "How do worker threads communicate with the main thread?", ["*By passing messages (structured clone), optionally transferring ArrayBuffers", "By reading and writing the same global variables", "Through environment variables", "Through the file system only"], "Workers have separate memory; SharedArrayBuffer is opt-in.");
  h("concurrency", "hard", "Why is exec(`convert ${fileName} out.png`) dangerous with user-supplied file names?", ["*exec runs a shell, so characters like ; can inject extra commands", "exec is slower than spawn", "exec can't handle spaces", "exec blocks the event loop"], "Use execFile/spawn with an argument array.");
  h("concurrency", "medium", "What does the cluster module do?", ["*Forks several worker processes that share one listening port", "Starts worker threads for each request", "Distributes data across databases", "Runs code on multiple machines"], "It lets one server use several CPU cores; state must live outside the processes.");
  h("concurrency", "hard", "What is 'partitioning' a long computation?", ["*Splitting it into chunks and yielding to the event loop (e.g. setImmediate) between them", "Running it in a worker thread", "Dividing it across cluster workers", "Caching its result"], "It keeps the server responsive, but still uses one core.");
  h("concurrency", "easy", "In the kitchen analogy, what are the libuv thread-pool threads?", ["*Kitchen porters doing slow tasks while the head chef keeps coordinating", "Delivery drivers outside the building", "Customers waiting for tables", "The head chef"], "The event loop is the head chef; the pool does slow chores; the network is delivery.");
  h("concurrency", "hard", "Why doesn't adding worker threads speed up a server that mainly waits for a database?", ["*The bottleneck is I/O waiting, which the event loop already handles concurrently", "Workers can't access the network", "Workers make the database slower", "Workers only run TypeScript"], "Workers help CPU-bound work, not I/O-bound work.");

  // ---------------------------------------------------------------- 14 testing
  h("testing", "easy", "Which command runs Node's built-in test runner and finds *.test.js files automatically?", ["*node --test", "npm run node-test", "node test", "node --check"], "It also finds files in test/ folders and *-test.js, *_test.js patterns.");
  h("testing", "easy", "Why import assert from \"node:assert/strict\"?", ["*Its equal and deepEqual use strict comparison (===, strict types)", "It runs assertions faster", "It is the only assert that works with node:test", "It prints coloured diffs only in strict mode"], "The legacy non-strict versions use == semantics.");
  h("testing", "medium", "What is the main risk of `assert.rejects(promise)` without await in a test?", ["*The test finishes before the assertion runs and may pass wrongly", "It throws a SyntaxError", "It makes the test run twice", "It disables other assertions"], "Make the test async and await every async assertion.");
  h("testing", "medium", "Which hook runs before every test in a describe block?", ["*beforeEach", "before", "after", "afterEach"], "Use it for fresh objects so tests stay independent.");
  h("testing", "medium", "How can you test code that calls the global fetch without network access?", ["*Replace it with mock.method(globalThis, \"fetch\", impl) and restore it afterwards", "Unplug the network", "Use fetch.mock = true", "Set NODE_ENV=test"], "Use t.mock.method so it's restored automatically.");
  h("testing", "medium", "What does t.mock.timers.tick(60_000) do?", ["*Advances the fake clock by one minute instantly, running due timers", "Waits one real minute", "Sets a 60-second timeout on the test", "Measures the test duration"], "Enable fake timers first with t.mock.timers.enable().");
  h("testing", "hard", "Why is 'dependency injection' (passing a pay function into checkout) useful for testing?", ["*Tests can pass a fake implementation and observe how it is called", "It makes the code run faster", "It removes the need for assertions", "It prevents all bugs"], "Injecting dependencies avoids mocking modules or the network.");
  h("testing", "medium", "What does code coverage tell you?", ["*Which lines, branches and functions the tests executed", "Whether the tests check the right behaviour", "How fast the code runs", "How many bugs remain"], "100% coverage with weak assertions can still miss bugs.");
  h("testing", "easy", "How do you start an HTTP server for tests without port conflicts?", ["*Listen on port 0 and read the assigned port from server.address()", "Always use port 3000", "Use a random number between 1 and 1000", "Start it in a separate terminal"], "Port 0 lets the OS choose a free port.");
  h("testing", "hard", "What makes a test 'flaky'?", ["*It passes or fails depending on uncontrolled factors like timing, network or randomness", "It takes more than one second", "It has more than one assertion", "It is marked as todo"], "Inject or mock clocks, randomness and network to make tests deterministic.");

  // ---------------------------------------------------------------- 15 production
  h("production", "easy", "Which flag pauses Node on the first line and waits for a debugger?", ["*--inspect-brk", "--inspect", "--debug", "--pause"], "Then open chrome://inspect or use VS Code.");
  h("production", "medium", "Why must the inspector never listen on a public network interface?", ["*Anyone who can connect can execute arbitrary code in the process", "It slows the server down", "It exposes environment variables only", "It breaks HTTPS"], "Keep it on 127.0.0.1 and use SSH tunnels for remote debugging.");
  h("production", "medium", "What is a memory leak in JavaScript?", ["*Objects you no longer need stay referenced, so the garbage collector can't free them", "The garbage collector stops working", "Memory used by native addons", "Using more than 1 GB of memory"], "Unbounded caches, forgotten listeners and timers are common causes.");
  h("production", "medium", "How do you find what is leaking memory?", ["*Compare heap snapshots taken over time and inspect what retains growing objects", "Restart the server every hour", "Call global.gc() repeatedly", "Increase --max-old-space-size"], "Chrome DevTools' Memory tab compares snapshots.");
  h("production", "medium", "What is the recommended reaction to an uncaught exception in production?", ["*Log it, then exit and let a supervisor restart a fresh process", "Ignore it and keep serving", "Retry the failed operation forever", "Disable the uncaughtException event"], "After an uncaught exception the process state is unknown.");
  h("production", "easy", "What does NODE_ENV=production mainly do?", ["*Tells libraries (Express, React…) to use their production behaviour", "Makes Node itself run faster", "Enables the permission model", "Disables console.log"], "Node itself ignores it; frameworks optimise and hide error details.");
  h("production", "medium", "Why compare secrets with crypto.timingSafeEqual instead of ===?", ["*=== stops at the first difference, leaking timing information to attackers", "=== doesn't work with strings", "timingSafeEqual is faster", "=== converts types"], "Constant-time comparison prevents timing attacks.");
  h("production", "hard", "Which input can cause prototype pollution in a naive deep-merge function?", ["*A JSON object with a \"__proto__\" key", "A very long string", "An empty object", "An array of numbers"], "Skip __proto__/constructor/prototype keys, use Map or Object.create(null).");
  h("production", "medium", "What does `node --permission --allow-fs-read=./data app.js` do?", ["*Denies everything except reading under ./data (no writes, child processes or other reads)", "Only logs file access", "Grants root permissions", "Encrypts ./data"], "Denied operations throw ERR_ACCESS_DENIED.");
  h("production", "hard", "What is the difference between liveness and readiness checks?", ["*Liveness: 'don't restart me'; readiness: 'send me traffic now'", "They are the same check", "Liveness checks the database; readiness checks CPU", "Readiness restarts the process"], "During startup and shutdown, readiness returns 503 while liveness stays 200.");

  // ---------------------------------------------------------------- 16 project
  h("project", "easy", "In the Chapter 16 project, why does createApp() return a server without calling listen()?", ["*So tests and scripts can start it on any port (e.g. 0) with their own store", "Because listen() is deprecated", "To make the server faster", "Because the router calls listen()"], "Factories with injected dependencies make the whole app testable.");
  h("project", "medium", "Why does NotesStore chain every save onto one promise (#saving)?", ["*So writes never overlap and an older snapshot can't overwrite a newer one", "To make reads faster", "Because writeFile can't run twice", "To compress the JSON"], "Like a print queue for one shared printer.");
  h("project", "medium", "Why does the store emit \"created\" only after the save succeeded?", ["*So listeners never announce a change that wasn't persisted", "Because emit is asynchronous", "To avoid the max-listeners warning", "Because SSE requires it"], "Events reflect completed, persisted changes.");
  h("project", "medium", "Which status does the project return for a POST /notes with Content-Type: text/plain?", ["*415", "400", "422", "404"], "readJson checks the content type first: 415 Unsupported Media Type.");
  h("project", "medium", "Which status does the project return for { \"text\": \"\" }?", ["*422", "400", "415", "201"], "The JSON is valid but the note fails validation: 422 with a details array.");
  h("project", "easy", "Which Node feature does the /events endpoint use to push changes to clients?", ["*Server-sent events: a long-lived response written to with res.write", "WebSockets", "Polling with setInterval on the client", "HTTP/2 push"], "Each store event becomes an event: / data: block on the open response.");
  h("project", "hard", "How does the /events route avoid leaking listeners when a client disconnects?", ["*It iterates events.on(store, …, { signal }) with a signal aborted on res 'close'", "It calls removeAllListeners on every request", "It limits the store to 10 listeners", "Listeners are garbage-collected automatically"], "Aborting the signal ends the iterators and removes their listeners.");
  h("project", "medium", "What does the project's smoke test check that the HTTP tests don't?", ["*The assembled system: the real server entry point driven by the real CLI", "Only the validation function", "The speed of the router", "The npm lockfile"], "It runs startServer() and the CLI as child processes.");
  h("project", "hard", "Why does the router return 405 for PUT /notes but 404 for GET /nothing?", ["*/notes exists with other methods; /nothing matches no route at all", "PUT is never allowed in HTTP", "404 is only for GET requests", "405 means the body is invalid"], "match() tracks whether any route matched the path.");
  h("project", "easy", "How many npm dependencies does the Chapter 16 project have?", ["*None", "One (express)", "Three", "It depends on the platform"], "Everything is built into Node: http, fs, events, test, util, crypto.");

  // ---------------------------------------------------------------- A typescript
  h("typescript", "easy", "What does Node do when it runs a .ts file?", ["*Strips the type annotations and runs the remaining JavaScript", "Type-checks the file and refuses to run on errors", "Compiles it to WebAssembly", "Sends it to the TypeScript compiler online"], "Type stripping doesn't check types; use tsc --noEmit for that.");
  h("typescript", "medium", "Which TypeScript features are NOT supported by Node's type stripping? (select all that apply)", ["*enum", "*parameter properties (constructor(private x: number))", "interface", "type aliases", "as casts"], "Only erasable syntax works; enums and parameter properties generate code.");
  h("typescript", "medium", "Why must type-only imports use `import type` when running TypeScript natively?", ["*The type doesn't exist in the JavaScript, so a value import of it fails at run time", "import type is faster", "Without it tsc refuses to compile", "Node can't read interfaces"], "verbatimModuleSyntax makes tsc enforce it.");
  h("typescript", "easy", "What extension do relative imports use in natively-run TypeScript?", ["*.ts (e.g. ./user.ts)", "No extension", ".js always", ".mjs"], "Node doesn't guess extensions; allowImportingTsExtensions lets tsc accept them.");
  h("typescript", "medium", "Which tsconfig option reports enums and parameter properties as errors?", ["*erasableSyntaxOnly", "strict", "noEmit", "skipLibCheck"], "It matches Node's strip-only rules.");
  h("typescript", "hard", "Why should a published npm package ship compiled JavaScript plus .d.ts files rather than .ts sources?", ["*Node doesn't strip types in node_modules, and consumers may not use TypeScript at all", "npm rejects .ts files", ".d.ts files run faster", "TypeScript sources can't be imported"], "Compile with declaration: true and point exports' types condition at the .d.ts.");
  h("typescript", "medium", "Do TypeScript types validate JSON coming from a request at run time?", ["*No; types are erased, so you must validate the data yourself", "Yes, automatically", "Only with strict mode", "Only for interfaces"], "Use unknown plus checks, or a schema library such as Zod.");
  h("typescript", "easy", "Which command type-checks a project without writing output files?", ["*npx tsc --noEmit", "node --check", "node --types", "npx tsc --run"], "Keep it in CI because running .ts doesn't check types.");
  h("typescript", "hard", "What is the idiomatic replacement for `enum Color { Red = \"red\" }` under type stripping?", ["*const Color = { Red: \"red\" } as const plus a derived union type", "A namespace", "A class with static fields and parameter properties", "A Symbol"], "Objects with as const work at run time and give precise types.");
  h("typescript", "medium", "In the margin-notes analogy, what does Node's type stripping do?", ["*Rubs out the notes and prints the text without proof-reading it", "Proof-reads the manuscript before printing", "Translates the book to another language", "Adds more notes"], "Stripping removes types; only tsc checks them.");

  // ---------------------------------------------------------------- B migrations
  h("migrations", "easy", "Which built-in replaces the chalk package for coloured terminal text?", ["*util.styleText", "console.color", "process.stdout.color", "util.inspect"], "styleText also respects NO_COLOR and non-TTY output.");
  h("migrations", "easy", "Which built-in replaces the uuid package's v4()?", ["*crypto.randomUUID()", "Math.random().toString(36)", "util.uuid()", "process.uuid"], "randomUUID generates RFC 4122 version 4 UUIDs.");
  h("migrations", "medium", "Migrating from axios to fetch, which behaviours must you add yourself? (select all that apply)", ["*Throwing on 4xx/5xx responses", "*Stringifying JSON bodies and setting Content-Type", "*Parsing the JSON response", "Sending the request at all"], "fetch resolves on HTTP errors and works with raw bodies.");
  h("migrations", "easy", "Which built-in replaces lodash's cloneDeep for plain data?", ["*structuredClone", "Object.assign", "JSON.parse(JSON.stringify(x)) only", "Array.from"], "structuredClone also handles Dates, Maps, Sets and cycles.");
  h("migrations", "medium", "Which built-ins replace rimraf and mkdirp?", ["*fs.rm with recursive/force and fs.mkdir with recursive", "fs.unlink and fs.mkdtemp", "fs.rmdir and fs.cp", "path.resolve and path.join"], "Both options were added to Node's fs module.");
  h("migrations", "medium", "What is a codemod in the context of Node's userland migrations?", ["*A tool that automatically rewrites source code, e.g. chalk calls to util.styleText", "A Node version manager", "A linter rule", "A runtime polyfill"], "Run on a clean git tree and review the diff.");
  h("migrations", "hard", "Why might a team keep yargs instead of switching to util.parseArgs?", ["*They rely on features parseArgs lacks, such as generated help and sub-commands", "parseArgs doesn't support booleans", "parseArgs is slower", "yargs is built into Node"], "parseArgs covers simple option parsing.");
  h("migrations", "medium", "What is WebAssembly used for in Node?", ["*Running portable compiled code (from Rust, C, Go…) without native compilation", "Running browser DOM code", "Compiling JavaScript to machine code", "Replacing npm"], "Node supports the same WebAssembly API as browsers.");
  h("migrations", "hard", "Why does ABI stability matter for Node-API addons?", ["*An addon compiled once keeps working across Node versions without recompiling", "It makes addons portable to browsers", "It removes the need for C++", "It lets addons run without the permission model"], "Node-API is a stable C interface independent of V8's internals.");
  h("migrations", "easy", "Which Node feature replaces the browser's localStorage for a server-side app?", ["*Files, node:sqlite or a database", "globalThis.localStorage", "process.env", "sessionStorage"], "Node has no Web Storage; persist data with fs or a database.");
}
